import torch
from torch import nn

class SmallCNN(nn.Module):
    def __init__(self, n_classes=10):
        super().__init__()
        self.features = nn.Sequential(
            nn.Conv2d(1, 16, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),   # 16 x 14 x 14
            nn.Conv2d(16, 32, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),  # 32 x 7 x 7
        )
        self.head = nn.Sequential(nn.Flatten(), nn.Linear(32 * 7 * 7, n_classes))

    def forward(self, x):
        return self.head(self.features(x))

model = SmallCNN()
x = torch.randn(8, 1, 28, 28)            # a batch of MNIST-sized images
print(model.features(x).shape)            # torch.Size([8, 32, 7, 7])
print(model(x).shape)                     # torch.Size([8, 10])

import torch
from torch.autograd import Function
class MyExp(Function):
    @staticmethod
    def forward(ctx, x):
        y = x.exp()
        ctx.save_for_backward(y)        # exp's derivative is exp itself
        return y
    @staticmethod
    def backward(ctx, grad_out):
        (y,) = ctx.saved_tensors
        return grad_out * y
class RoundSTE(Function):
    @staticmethod
    def forward(ctx, x):
        return x.round()
    @staticmethod
    def backward(ctx, grad_out):
        return grad_out                 # pretend round() was identity

x = torch.randn(3, dtype=torch.double, requires_grad=True)
print(torch.autograd.gradcheck(MyExp.apply, (x,)))   # True
z = torch.tensor([0.4, 1.6], requires_grad=True)
RoundSTE.apply(z).sum().backward()
print(z.grad)                           # tensor([1., 1.])  (true derivative is 0)

import torch
from torch import Tensor

@torch.library.custom_op("mylib::scaled_tanh", mutates_args=())
def scaled_tanh(x: Tensor, scale: float) -> Tensor:
    return torch.tanh(x) * scale        # could call Triton, C++ or NumPy here

@scaled_tanh.register_fake
def _(x, scale):
    return torch.empty_like(x)          # shapes/dtypes only, used while tracing

def setup_context(ctx, inputs, output):
    _, scale = inputs
    ctx.save_for_backward(output)
    ctx.scale = scale

def backward(ctx, grad):
    (y,) = ctx.saved_tensors
    return grad * ctx.scale * (1 - (y / ctx.scale) ** 2), None

scaled_tanh.register_autograd(backward, setup_context=setup_context)

x = torch.randn(4, requires_grad=True)
torch.ops.mylib.scaled_tanh(x, 2.0).sum().backward()
print(x.grad.shape)                     # torch.Size([4])
